// Reproducible sanitized analogues of real incident classes, never user data.
import PptxGenJS from 'pptxgenjs';
import sharp from 'sharp';
import { mkdir } from 'node:fs/promises';
const output = process.argv[2] || '/tmp/mcl-compiler-corpus';
await mkdir(output, {recursive:true});
const deck = new PptxGenJS(); deck.layout='LAYOUT_WIDE';
const title = (slide,text) => slide.addText(text,{x:.4,y:.2,w:12.4,h:.55,fontSize:28,bold:true});
let slide=deck.addSlide(); title(slide,'RECURSOS RECEBIDOS');
slide.addChart(deck.ChartType.bar,[{name:'Recebido',labels:['PI A','PI B'],values:[80,20]}],{x:.7,y:1.2,w:12,h:5.7,catAxisLabelFontSize:18,valAxisLabelFontSize:18,showLegend:true,showValue:true});
slide.addText('86% disponíveis',{x:3.2,y:2,w:2.5,h:.5,fontSize:24,bold:true,color:'FFFFFF',fill:{color:'4472C4'}});
slide=deck.addSlide(); title(slide,'RELATÓRIO DE TRANSPORTE PARA RIO DE JANEIRO');
['Origem: Alpha','Destino: Beta','Meio: terrestre','Quantidade: 42','Prazo: 15 dias','Situação: concluída'].forEach((text,i)=>slide.addText(text,{x:.8,y:1.1+i*.9,w:11.8,h:.7,fontSize:24}));
slide=deck.addSlide();
const cover=await sharp(Buffer.from('<svg xmlns="http://www.w3.org/2000/svg" width="1920" height="1080"><rect width="1920" height="1080" fill="#123a31"/><text x="960" y="570" text-anchor="middle" font-family="sans-serif" font-size="120" fill="white">CAPA INTEGRAL</text></svg>')).png().toBuffer();
slide.addImage({data:'image/png;base64,'+cover.toString('base64'),x:0,y:0,w:13.333,h:7.5});
slide=deck.addSlide(); title(slide,'EXECUÇÃO ORÇAMENTÁRIA DO 9º B MNT');
slide.addText('Total: 100\nRecebido: 80\nSaldo: 20',{x:.8,y:1.3,w:11.8,h:4,fontSize:32});
slide=deck.addSlide(); title(slide,'GRÁFICO COMBINADO');
slide.addChart([{type:deck.ChartType.bar,data:[{name:'Volume',labels:['A','B'],values:[80,20]}]},{type:deck.ChartType.line,data:[{name:'Prazo',labels:['A','B'],values:[3,6]}]}],{x:.6,y:1.2,w:12.2,h:5.7,showLegend:true});
slide=deck.addSlide(); title(slide,'NOTA COM OBJETOS MISTURADOS');
slide.addShape(deck.ShapeType.rect,{x:.5,y:1.2,w:12,h:5.5,fill:{color:'F8FAFC'},line:{color:'F8FAFC'}});
slide.addText('Informação dentro da forma: 42',{x:.9,y:1.6,w:11,h:.8,fontSize:28});
slide.addImage({data:'image/png;base64,'+cover.toString('base64'),x:11.7,y:5.8,w:1,h:.55});
slide=deck.addSlide(); title(slide,'RELATÓRIO EXTENSO');
for(let i=0;i<24;i++) slide.addText('Registro '+(i+1)+': conteúdo integral que deve permanecer na sequência, com valores '+(100+i),{x:.6,y:1+i*.24,w:12,h:.24,fontSize:14});
slide=deck.addSlide(); title(slide,'EXECUÇÃO POR PI');
slide.addChart(deck.ChartType.bar,[{name:'Recebido',labels:['PI A','PI B','PI C'],values:[50,30,20]}],{x:.8,y:1.2,w:11.8,h:5.8,showValue:true,showLegend:true});
await deck.writeFile({fileName:output+'/heterogeneous.pptx'});
console.log(output+'/heterogeneous.pptx');
